<section class="view active contact-page">
  <div class="container page-top"><span class="eyebrow">Contact TaskHaat</span><h1>How can we help?</h1><p>Send a support request about an account, campaign, submission, wallet or safety concern.</p></div>
  <div class="container contact-content">
    <aside class="contact-info"><span class="contact-info-icon"><i data-lucide="messages-square"></i></span><h2>Support requests</h2><p>Your message is saved securely in the TaskHaat Admin support inbox. This local build does not send email notifications to an external mailbox.</p><div class="contact-info-row"><i data-lucide="clock-3"></i><span><strong>Review process</strong><small>An Admin can review and update the request status.</small></span></div><div class="contact-info-row"><i data-lucide="shield-check"></i><span><strong>Keep it private</strong><small>Never include your password, OTP, PIN or full payment credentials.</small></span></div><a href="<?=e(url('help'))?>" class="contact-help-link">Check the Help Center first <i data-lucide="arrow-up-right"></i></a></aside>
    <section class="panel contact-form-panel"><div class="panel-head"><div><h2>Send a support request</h2><p>Fields marked with * are required.</p></div><span class="pill green">Support inbox</span></div><div class="panel-body">
      <form method="post" class="contact-form"><?=csrf_field()?><input type="hidden" name="action" value="contact_support"><input type="hidden" name="_return" value="contact">
        <div class="form-grid"><div class="field"><label for="supportName">Your name <span class="req">*</span></label><input id="supportName" name="name" required maxlength="120" value="<?=e($user?($user['first_name'].' '.$user['last_name']):'')?>" autocomplete="name"></div><div class="field"><label for="supportEmail">Email address <span class="req">*</span></label><input id="supportEmail" type="email" name="email" required maxlength="190" value="<?=e($user['email']??'')?>" autocomplete="email"></div><div class="field full"><label for="supportSubject">Topic <span class="req">*</span></label><select id="supportSubject" name="subject" required><option value="">Choose a topic</option><option value="Account and login" <?=($_GET['topic']??'')==='account'?'selected':''?>>Account and login</option><option value="Campaign or task" >Campaign or task</option><option value="Submission review">Submission review</option><option value="Wallet or withdrawal">Wallet or withdrawal</option><option value="Safety concern" <?=($_GET['topic']??'')==='safety'?'selected':''?>>Safety concern</option><option value="Other">Other</option></select></div><div class="field full"><label for="supportMessage">How can we help? <span class="req">*</span></label><textarea id="supportMessage" name="message" required minlength="20" maxlength="4000" rows="7" placeholder="Explain what happened, which page or campaign is involved and what you need help with. Please do not include passwords or OTPs."></textarea><small>20–4,000 characters. Do not include account passwords, OTPs or bank PINs.</small></div><div class="field full contact-honeypot" aria-hidden="true"><label for="companyWebsite">Leave this field empty</label><input id="companyWebsite" name="company_website" tabindex="-1" autocomplete="off"></div></div>
        <button class="btn" type="submit"><i data-lucide="send"></i> Submit support request</button>
      </form>
    </div></section>
  </div>
